{
   return iMA(NULL, 0, period, 0, MODE_EMA, PRICE_CLOSE, 0);
}

//+------------------------------------------------------------------+
//| Verifica condições de compra                                     |
//+------------------------------------------------------------------+
bool CheckBuyCondition(double ema)
{
   if (Close[1] < ema && Close[0] > ema) return true;
   return false;
}

//+------------------------------------------------------------------+
//| Verifica condições de venda                                      |
//+------------------------------------------------------------------+
bool CheckSellCondition(double ema)
{
   if (Close[1] > ema && Close[0] < ema) return true;
   return false;
}

//+------------------------------------------------------------------+
//| Atualizar Linhas Gráficas (Fixado ao Objeto)                     |
//+------------------------------------------------------------------+
void UpdateEMALine()
{
   double current_ema = CalculateEMA(EMA_Period);

   if (!ema_created) {
      // Cria o objeto só uma vez ao iniciar
      ObjectCreate(0, "EMA_45", OBJ_TREND, 0, Time[0], 
                   0, current_ema);    // Tempo e preço
      ObjectSetInteger(0, "EMA_45", OBJPROP_COLOR, clrBlue);
      ObjectSetInteger(0, "EMA_45", OBJPROP_WIDTH, 2); // Largura da linha
      ema_created = true;
   } else {
      // Atualiza a posição da linha sem criar nova
      ObjectMove(0, "EMA_45", 0, current_ema);
   }
}

//+------------------------------------------------------------------+
//| Função para o OnTick                                              |
//+------------------------------------------------------------------+
void OnTick()
{
   if (Symbol() != "XAUUSD") return;

   // Atualiza a linha gráfica antes de verificar sinais
   UpdateEMALine();

   // Sinal de COMPRA
   if (CheckBuyCondition(CalculateEMA(EMA_Period)) && OrdersTotal() == 0)
   {
      double stop_loss_buy = iLow(NULL, 0, iLowest(NULL, 0, MODE_LOW, 10, 1));
      double take_profit_buy = Close[0] + (Close[0] - stop_loss_buy) * Risk_Reward_Ratio;

