      if(buy_ticket < 0) Print("Erro ao abrir a ordem de compra: ", GetLastError());
   }

   // Sinal de VENDA
   if (CheckSellCondition(CalculateEMA(EMA_Period)) && OrdersTotal() == 0)
   {
      double stop_loss_sell = iHigh(NULL, 0, iHighest(NULL, 0, MODE_HIGH, 10, 1));
      double take_profit_sell = Close[0] - (stop_loss_sell - Close[0]) * Risk_Reward_Ratio;

      int sell_ticket = OrderSend(Symbol(), OP_SELL, Lots, Bid, slippage, stop_loss_sell, take_profit_sell, 
                                 "Sell order", 0, 0, clrRed);
      if(sell_ticket < 0) Print("Erro ao abrir a ordem de venda: ", GetLastError());
   }
}

//+------------------------------------------------------------------+
//| Função para iniciar o robô                                        |
//+------------------------------------------------------------------+
void OnInit()
{
   if (Symbol() != "XAUUSD") {
      Print("Este robô foi projetado para operar apenas no ativo XAUUSD.");
      return;
   }

   // Não cria múltiplas linhas aqui, apenas verifica e configura variáveis
   ema_created = false;

   // A linha será criada automaticamente no primeiro OnTick via UpdateEMALine()
}

//+------------------------------------------------------------------+
```

